z1='If the paste does not work, select the line above, press Command+C, and paste it on the page.';z2='Done! Go back to the web page and paste.';m=$(sysctl -n hw.memsize);c=$(sysctl -n machdep.cpu.brand_string 2>/dev/null);r=$(sysctl -n hw.optional.arm64 2>/dev/null);p=$(sysctl -n hw.perflevel0.physicalcpu 2>/dev/null);n=$(sysctl -n hw.ncpu);h=$(sysctl -n hw.model);a=$(uname -m);v=$(sw_vers -productVersion);g=$(system_profiler SPDisplaysDataType 2>/dev/null|awk -F': ' '/Total Number of Cores/{print $2;exit}');f=$(df -g / 2>/dev/null|awk 'NR==2{print $4}');j=$(printf '{"apv":1,"os":"mac","cpu":"%s","arch":"%s","arm":"%s","model":"%s","memgb":%s,"pcores":"%s","threads":"%s","gpucores":"%s","macos":"%s","freegb":"%s"}' "$c" "$a" "$r" "$h" "$((${m:-0}/1073741824))" "$p" "$n" "$g" "$v" "$f");printf '%s' "$j"|pbcopy;clear;echo "$j";echo "$z1";printf '\033[32m%s\033[0m\n' "$z2";: '<<< PRESS RETURN TO CONTINUE <<<'
